// Екранує спеціальні символи для RegExp
function escapeRegExp(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

// Функція нормалізації тексту
function normalizeText(str) {
  return str
    ? str
        .normalize("NFD")                // розклад на символ + діакритики
        .replace(/[\u0300-\u036f]/g, "") // прибираємо діакритики
        .replace(/[’‘]/g, "'")           // нормалізація апострофів
        .trim()
    : str;
}

function replaceWords(text, productReplacedWords) {
  if (!text) return text;
  let normalized = normalizeText(text);

  for (const [word, replacement] of Object.entries(replaceList)) {
    const regex = new RegExp("\\b" + escapeRegExp(normalizeText(word).toLowerCase()) + "\\b", "giu");
    if (regex.test(normalized.toLowerCase())) {
      productReplacedWords.push({ word, replacement });
      normalized = normalized.replace(regex, replacement);
    }
  }

  return normalized;
}

return items.map(item => {
  if (!item.json || !item.json.product) return { json: { product: {} } };

  const product = item.json.product;
  const replacedWords = [];

  keysToCheck.forEach(key => {
    if (typeof product[key] === "string") {
      product[key] = replaceWords(product[key], replacedWords);
    }
  });

  product.replacedWords = replacedWords;

  return { json: { product } };
});

